// Set up the main workflow for this Laravel+Vite app
// Laravel serves on port 8000, Vite HMR on 5173
// The webview port must be 5000, so we need a combined command
// that starts both and proxies on port 5000, OR
// we use Laravel's built-in server with Vite serving assets separately

// For Replit, the main workflow needs to serve on port 5000
// We'll run both Laravel (port 8000) and a simple proxy on port 5000
// OR just use php artisan serve on 0.0.0.0:5000 with vite on a different port

const result = await configureWorkflow({
    name: "Start application",
    command: "php artisan serve --host=0.0.0.0 --port=5000 & npm run dev",
    waitForPort: 5000,
    outputType: "webview"
});
console.log(JSON.stringify(result, null, 2));

const status = await getWorkflowStatus({ name: "Start application", maxScrollbackLines: 50 });
console.log(`State: ${status.state}`);
console.log(`Ports: ${JSON.stringify(status.openPorts)}`);
console.log(`Output:\n${status.output}`);

// Update APP_URL to use port 5000 since that's what the workflow uses
const result = await setEnvVars({
    values: {
