   477→        $currentSemester = Semester::where('is_current', true)->first();
   478→
   479→        // Get all courses inside this tenant
   480→        $courses = Course::where('tenant_id', $tenant->id)
   481→            ->with(['lecturer.user', 'department'])
   482→            ->get()
   483→            ->map(function ($course) use ($currentSemester) {
   484→                // Get registrations with grades
   485→                $registrations = CourseRegistration::where('course_id', $course->id)
   486→                    ->where('semester_id', $currentSemester?->id)
   487→                    ->with(['student.user', 'grade'])
   488→                    ->get();
   489→
   490→                $grades = $registrations->map(fn($r) => $r->grade)->filter();
   491→                $totalGraded = $grades->count();
   492→
   493→                $passed = $grades->filter(fn($g) => $g->grade_letter !== 'F' && $g->grade_letter !== 'ABS' && $g->grade_letter !== null)->count();
   494→                $failed = $grades->filter(fn($g) => $g->grade_letter === 'F')->count();
   495→                $absent = $grades->filter(fn($g) => $g->is_absent == true || $g->grade_letter === 'ABS')->count();
   496→                $averageScore = $grades->filter(fn($g) => !$g->is_absent)->avg('total_score') ?? 0;
   497→
   498→                // Overall status:
   499→                // Released: if there are grades and all are 'approved'
   500→                // Pending Registrar Release: if grades contain 'hod_approved' and none are 'draft'/'submitted'
   501→                // Pending HOD/Lecturer: otherwise
   502→                $status = 'no_grades';
   503→                if ($totalGraded > 0) {
   504→                    $hasReleased = $grades->contains(fn($g) => $g->approval_status === 'approved');
   505→                    $hasHODApproved = $grades->contains(fn($g) => $g->approval_status === 'hod_approved');
   506→                    $hasSubmitted = $grades->contains(fn($g) => $g->approval_status === 'submitted');
   507→
   508→                    if ($hasReleased) {
   509→                        $status = 'released';
   510→                    } elseif ($hasHODApproved) {
   511→                        $status = 'pending_release';
   512→                    } elseif ($hasSubmitted) {
